#!/usr/bin/env python3
"""Generate the next order id based on ids.txt (one id per line, most recent last).

Ids have the form ORD- followed by four sequential base-36 characters.
"""

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 36


def increment(code):
    """Return the base-36 successor of the 4-character code, zero-padded."""
    value = 0
    for ch in code:
        value = value * BASE + ALPHABET.index(ch)
    value += 1

    result = []
    while value:
        value, rem = divmod(value, BASE)
        result.append(ALPHABET[rem])
    return "".join(reversed(result)).zfill(4)


def main():
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        next_code = "0000"
    else:
        last = lines[-1]          # e.g. "ORD-243G"
        next_code = increment(last[4:])  # last 4 chars are the code

    print("ORD-" + next_code)


if __name__ == "__main__":
    main()
