#!/usr/bin/env python3
"""Read ids.txt (one order id per line, most recent last) and print the next id."""

import pathlib

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def _from_base36(s: str) -> int:
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def _to_base36(n: int, width: int) -> str:
    chars = []
    for _ in range(width):
        chars.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(chars))


def next_id(current: str) -> str:
    prefix, suffix = current.split("-")
    assert len(suffix) == 4
    n = _from_base36(suffix) + 1
    next_suffix = _to_base36(n, 4)
    return f"{prefix}-{next_suffix}"


def main() -> None:
    lines = pathlib.Path("ids.txt").read_text().strip().splitlines()
    # Filter blank lines and grab the last valid id
    ids = [line.strip() for line in lines if line.strip()]
    if not ids:
        raise SystemExit("error: ids.txt is empty")

    last_id = ids[-1]
    print(next_id(last_id))


if __name__ == "__main__":
    main()

