import sys

def next_id(ids):
    """Return the next ID after the most recent one, using base36."""
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    base = len(chars)
    char_to_val = {c: i for i, c in enumerate(chars)}

    if not ids:
        return 'ORD-' + ('0' * 4)

    last = ids[-1]
    # Extract the 4-character suffix
    suffix = last.replace('ORD-', '')
    if len(suffix) != 4:
        raise ValueError(f"Unexpected suffix format: {suffix}")

    # Convert to integer
    val = 0
    for ch in suffix:
        val = val * base + char_to_val[ch.upper()]

    # Increment
    val += 1

    # Convert back to base36
    result = []
    for _ in range(4):
        result.append(chars[val % base])
        val //= base
    result.reverse()

    return 'ORD-' + ''.join(result)


def main():
    with open('ids.txt', 'r') as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        print('ORD-0000')
        return

    print(next_id(lines))


if __name__ == '__main__':
    main()

