#!/usr/bin/env python3
"""Generate manifest.json: SHA-256 digests of every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the hex SHA-256 digest of *path*."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def build_manifest() -> dict[str, str]:
    """Collect every regular file under release/, keyed by its relative path."""
    manifest: dict[str, str] = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel = str(path.relative_to(RELEASE_DIR.parent))  # e.g. "release/VERSION"
            manifest[rel] = sha256_digest(path)
    return manifest


def main() -> None:
    manifest = build_manifest()
    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

