"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(filepath: Path) -> str:
    return hashlib.sha256(filepath.read_bytes()).hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    if not RELEASE_DIR.is_dir():
        print(f"error: {RELEASE_DIR} does not exist")
        raise SystemExit(1)

    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel = str(path.relative_to("."))
            manifest[rel] = sha256_digest(path)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()
PYEOF

