"""Rotate old entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every entry in app.log
whose timestamp is strictly older than 7 days before AS_OF is moved
to archive.log (appended, preserving order). The remaining entries
rewrite app.log in their original order.
"""

import sys
from datetime import datetime, timezone, timedelta

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
SECONDS_IN_7_DAYS = 7 * 86400


def parse_timestamp(line: str) -> datetime | None:
    """Extract the leading YYYY-MM-DD HH:MM:SS timestamp from a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff_dt = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(
        seconds=SECONDS_IN_7_DAYS
    )

    try:
        with open(LOG_FILE, "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found.", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        # Preserve blank lines (keep them where they are)
        stripped = line.rstrip("\n")
        if not stripped:
            keep.append(line)
            continue

        ts = parse_timestamp(stripped)
        if ts is None:
            # Lines without a parseable timestamp stay in app.log
            keep.append(line)
            continue

        if ts < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    with open(LOG_FILE, "w") as f:
        f.writelines(keep)

    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()

