        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff_dt = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(
        seconds=SECONDS_IN_7_DAYS
    )

    try:
        with open(LOG_FILE, "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found.", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        stripped = line.rstrip("\n")
        if not stripped:
            keep.append(line)
            continue

        ts = parse_timestamp(stripped)
        if ts is None:
            keep.append(line)
            continue

        if ts < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    with open(LOG_FILE, "w") as f:
        f.writelines(keep)

    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()
